{{ config( materialized='incremental', alias='etl_process', schema='FIVETRAND_DB_1', pre_hook="", post_hook="", incremental_strategy='merge', unique_key=['etl_job_id'], merge_update_columns=['etl_job_end'] ) }} With sql_etl_processOut AS ( SELECT * FROM ( SELECT MAX(etl_process.etl_job_id) FROM etl_process WHERE ETL_PROCESS.ETL_JOB_NAME = 'DSDOLLARPMSESSIONNAME' AND ETL_PROCESS.ETL_JOB_END IS NULL ) ), exp_CONSOLIDATE_1Out AS ( SELECT etl_job_id AS etl_job_id, dsCurrentTimestamp () AS oSYSDATE FROM sql_etl_processOut AS sql_etl_processOut ) Select etl_job_id as etl_job_id, etl_process_seq.nextval as etl_source_system_code, etl_process_seq.nextval as extract_stamp, oSYSDATE as etl_job_end From exp_CONSOLIDATE_1Out as exp_CONSOLIDATE_1Out;